import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing the same reduction as the CuTe/CUDA kernel:
#
#   Y[o, i] = max_r X[o, r, i]
#
# where X is viewed (per outer slice `o`) as a (R, inner) row-major matrix.
# Grid.x*Block.x covers `inner`, Grid.y covers `outer`.
#
# Optimization applied: the serial reduction loop over R has been unrolled
# by a factor of 4 with independent (non-dependent) global loads combined
# via a small max-reduction tree. Because the four loads inside one
# unrolled iteration have no data dependency on each other, the hardware
# can issue/overlap them, increasing memory-level parallelism and hiding
# global memory latency compared to the strictly serial
# load->compare->select chain of the original loop. A scalar tail loop
# still handles any remaining rows (R may not be a multiple of 4), and all
# original bounds/predicate checks and address arithmetic are preserved so
# behavior is unchanged.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry max_reduce_kernel(
    .param .u64 max_reduce_kernel_param_0,
    .param .u64 max_reduce_kernel_param_1,
    .param .u32 max_reduce_kernel_param_2,
    .param .u32 max_reduce_kernel_param_3,
    .param .u32 max_reduce_kernel_param_4
)
{
    .reg .pred %p<14>;
    .reg .f32 %f<9>;
    .reg .b32 %r<14>;
    .reg .b64 %rd<24>;

    ld.param.u64 %rd1, [max_reduce_kernel_param_0];   // X ptr
    ld.param.u64 %rd2, [max_reduce_kernel_param_1];   // Y ptr
    ld.param.u32 %r1,  [max_reduce_kernel_param_2];   // outer
    ld.param.u32 %r2,  [max_reduce_kernel_param_3];   // R
    ld.param.u32 %r3,  [max_reduce_kernel_param_4];   // inner

    cvta.to.global.u64 %rd3, %rd1;
    cvta.to.global.u64 %rd4, %rd2;

    mov.u32 %r4, %ctaid.y;          // o
    mov.u32 %r5, %ctaid.x;
    mov.u32 %r6, %ntid.x;
    mov.u32 %r7, %tid.x;
    mad.lo.s32 %r8, %r5, %r6, %r7;  // i = blockIdx.x*blockDim.x + threadIdx.x

    setp.ge.s32 %p1, %r4, %r1;
    setp.ge.s32 %p2, %r8, %r3;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    cvt.s64.s32 %rd5, %r4;   // o
    cvt.s64.s32 %rd6, %r2;   // R
    cvt.s64.s32 %rd7, %r3;   // inner
    cvt.s64.s32 %rd8, %r8;   // i

    // base = o*R*inner + i
    mul.lo.s64 %rd9,  %rd5, %rd6;
    mul.lo.s64 %rd10, %rd9, %rd7;
    add.s64 %rd11, %rd10, %rd8;

    shl.b64 %rd12, %rd11, 2;
    add.s64 %rd13, %rd3, %rd12;      // &X[o,0,i]

    ld.global.f32 %f1, [%rd13];      // maxval = X[o,0,i]

    mov.u32 %r9, 1;
    setp.lt.s32 %p4, %r2, 2;
    @%p4 bra STORE;

    shl.b64 %rd14, %rd7, 2;          // row stride in bytes = inner*4
    add.s64 %rd15, %rd13, %rd14;     // ptr to row 1

    // -------------------------------------------------------------
    // Unrolled (x4) section: 4 independent loads issued together,
    // then combined with a small max-reduction tree, to increase
    // memory-level parallelism versus a purely serial loop.
    // -------------------------------------------------------------
CHECK_UNROLL:
    sub.s32 %r10, %r2, %r9;
    setp.lt.s32 %p7, %r10, 4;
    @%p7 bra TAIL_LOOP;

UNROLL_LOOP:
    ld.global.f32 %f2, [%rd15];
    add.s64 %rd20, %rd15, %rd14;
    ld.global.f32 %f3, [%rd20];
    add.s64 %rd21, %rd20, %rd14;
    ld.global.f32 %f4, [%rd21];
    add.s64 %rd22, %rd21, %rd14;
    ld.global.f32 %f5, [%rd22];

    setp.gt.f32 %p8, %f3, %f2;
    selp.f32 %f6, %f3, %f2, %p8;      // m01 = max(row0,row1)
    setp.gt.f32 %p9, %f5, %f4;
    selp.f32 %f7, %f5, %f4, %p9;      // m23 = max(row2,row3)
    setp.gt.f32 %p10, %f7, %f6;
    selp.f32 %f8, %f7, %f6, %p10;     // m0123 = max(m01,m23)
    setp.gt.f32 %p11, %f8, %f1;
    selp.f32 %f1, %f8, %f1, %p11;     // maxval = max(maxval, m0123)

    add.s64 %rd15, %rd22, %rd14;      // advance pointer past 4 rows
    add.s32 %r9, %r9, 4;
    sub.s32 %r10, %r2, %r9;
    setp.ge.s32 %p12, %r10, 4;
    @%p12 bra UNROLL_LOOP;

TAIL_LOOP:
    setp.lt.s32 %p6, %r9, %r2;
    @%p6 bra TAIL_BODY;
    bra STORE;

TAIL_BODY:
    ld.global.f32 %f2, [%rd15];
    setp.gt.f32 %p5, %f2, %f1;
    selp.f32 %f1, %f2, %f1, %p5;
    add.s64 %rd15, %rd15, %rd14;
    add.s32 %r9, %r9, 1;
    setp.lt.s32 %p6, %r9, %r2;
    @%p6 bra TAIL_BODY;

STORE:
    // out_offset = o*inner + i
    mul.lo.s64 %rd16, %rd5, %rd7;
    add.s64 %rd17, %rd16, %rd8;
    shl.b64 %rd18, %rd17, 2;
    add.s64 %rd19, %rd4, %rd18;
    st.global.f32 [%rd19], %f1;

DONE:
    ret;
}
"""

_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """Sanity check that the PTX module contains the expected entry point."""
    module = _get_module()
    entry = module.function("max_reduce_kernel")
    assert entry is not None, "max_reduce_kernel entry not found in PTX module"
    return entry


class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension, implemented as a hand-written
    PTX kernel executed via cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        ndim = x_c.dim()

        dim = self.dim
        if dim < 0:
            dim += ndim
        assert 0 <= dim < ndim, "dim out of range"

        sizes = x_c.shape

        outer = 1
        for d in range(dim):
            outer *= sizes[d]
        R = sizes[dim]
        inner = 1
        for d in range(dim + 1, ndim):
            inner *= sizes[d]

        out_shape = [sizes[d] for d in range(ndim) if d != dim]
        y = torch.empty(out_shape, device=x_c.device, dtype=x_c.dtype)

        threads = 256
        grid_x = (inner + threads - 1) // threads
        grid_y = outer

        module = _get_module()
        stream = torch.cuda.current_stream().cuda_stream

        module.launch(
            "max_reduce_kernel",
            grid=(grid_x, grid_y, 1),
            block=(threads, 1, 1),
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(y.data_ptr()),
                i32(outer),
                i32(R),
                i32(inner),
            ],
        )

        return y

